def concept_spotter_v1(text):
    known = ['brain', 'nervous', 'central', 'information', 'sensory', 'activities', 'consciousness', 'considered', 'explanations', 'analyses', 'aspect', 'aware', 'earth', 'water', 'crust', 'ocean', 'solar', 'astronomical', 'study', 'algorithms', 'artificial', 'concerned', 'development', 'explicitly']
    t = str(text).lower()
    found = [c for c in known if c in t]
    return sorted(set(found))

